using System;using System.Linq;using System.Threading.Tasks;using UnityEngine;using Codice.Mechanics;using Codice.Enemies;
public static class CemeteryRegression {
 public static string CrossToBoss(){var r=RunDirector.Instance;var f=r.Expedition;if(!f.InEncounter)throw new Exception("Expected unfinished normal encounter");var cc=r.Player.GetComponent<CharacterController>();cc.enabled=false;r.Player.transform.position=f.Center(f.Layout.Boss)+Vector3.back*(f.Layout.Radius(f.Layout.Boss)*4-3);cc.enabled=true;return "Crossed to boss without clearing previous enemies, reproducing JAM free roam";}
 public static async Task<string> Feet(){float min=999,max=-999;int samples=0;for(int i=0;i<80;i++){var e=UnityEngine.Object.FindObjectsByType<BasicEnemy>().FirstOrDefault(x=>x.name.StartsWith("Executioner"));if(e){var a=e.animator;float y=Mathf.Min(a.GetBoneTransform(HumanBodyBones.LeftFoot).position.y,a.GetBoneTransform(HumanBodyBones.RightFoot).position.y)-e.transform.position.y;min=Mathf.Min(min,y);max=Mathf.Max(max,y);samples++;}await Task.Delay(50);}if(samples<20||min<-.05f||max>.2f)throw new Exception("Feet "+samples+" "+min+"/"+max);return "PASS "+samples+" live foot samples: "+min+" to "+max;}
}
